def forward(groups):
    whole, frac = groups[2], groups[3]
    return {
        'stored': [int(whole) * 10 + int(frac)],
        'layout': [len(groups[1]), len(groups[2])]
    }

def inverse(record):
    value = int(record['stored'][0])
    layout = record.get('layout', [])
    sp1_len, whole_width = layout
    whole = str(value // 10).zfill(whole_width)
    frac = str(value % 10)
    return '(estimated' + (' ' * sp1_len) + 'size ' + whole + '.' + frac
